﻿/**
 * @fileoverview Perft (Performance Test) move path enumerator.
 * 
 * WHY: Canonical validation technique to verify engine legality against known benchmark positions.
 */

import { Color, Piece } from './types.js';
import {
  applyMoveInternal,
  generateLegalMoves,
  isColorInCheck,
  unapplyMoveInternal,
} from './move-generator.js';
import { BITS, CASTLE_FLAGS, SQUARES, WHITE, BLACK } from './constants.js';
import { squareToAlgebraic, swapColor } from './utils.js';

export function perft(
  board: (Piece | null)[],
  turn: Color,
  castling: number,
  epSquare: number,
  depth: number
): number {
  if (depth === 0) return 1;

  const moves = generateLegalMoves(board, turn, castling, epSquare);
  if (depth === 1) return moves.length;

  let nodes = 0;

  for (const move of moves) {
    const prevCastling = castling;
    const prevEpSquare = epSquare;

    const undo = applyMoveInternal(board, move);

    // Update EP square
    let nextEpSquare = -1;
    if (move.flags & BITS.BIG_PAWN) {
      nextEpSquare = move.color === WHITE ? move.from - 16 : move.from + 16;
    }

    // Update castling rights
    let nextCastling = castling;
    if (move.piece === 'k') {
      if (move.color === WHITE) {
        nextCastling &= ~(CASTLE_FLAGS.WHITE_OO | CASTLE_FLAGS.WHITE_OOO);
      } else {
        nextCastling &= ~(CASTLE_FLAGS.BLACK_OO | CASTLE_FLAGS.BLACK_OOO);
      }
    }
    if (move.from === SQUARES.h1 || move.to === SQUARES.h1) nextCastling &= ~CASTLE_FLAGS.WHITE_OO;
    if (move.from === SQUARES.a1 || move.to === SQUARES.a1) nextCastling &= ~CASTLE_FLAGS.WHITE_OOO;
    if (move.from === SQUARES.h8 || move.to === SQUARES.h8) nextCastling &= ~CASTLE_FLAGS.BLACK_OO;
    if (move.from === SQUARES.a8 || move.to === SQUARES.a8) nextCastling &= ~CASTLE_FLAGS.BLACK_OOO;

    nodes += perft(board, swapColor(turn), nextCastling, nextEpSquare, depth - 1);

    unapplyMoveInternal(board, move, undo);
  }

  return nodes;
}

export function perftDivide(
  board: (Piece | null)[],
  turn: Color,
  castling: number,
  epSquare: number,
  depth: number
): Record<string, number> {
  const result: Record<string, number> = {};
  const moves = generateLegalMoves(board, turn, castling, epSquare);

  for (const move of moves) {
    const uci = `${squareToAlgebraic(move.from)}${squareToAlgebraic(move.to)}${move.promotion || ''}`;
    const undo = applyMoveInternal(board, move);

    let nextEpSquare = -1;
    if (move.flags & BITS.BIG_PAWN) {
      nextEpSquare = move.color === WHITE ? move.from - 16 : move.from + 16;
    }

    let nextCastling = castling;
    if (move.piece === 'k') {
      if (move.color === WHITE) {
        nextCastling &= ~(CASTLE_FLAGS.WHITE_OO | CASTLE_FLAGS.WHITE_OOO);
      } else {
        nextCastling &= ~(CASTLE_FLAGS.BLACK_OO | CASTLE_FLAGS.BLACK_OOO);
      }
    }
    if (move.from === SQUARES.h1 || move.to === SQUARES.h1) nextCastling &= ~CASTLE_FLAGS.WHITE_OO;
    if (move.from === SQUARES.a1 || move.to === SQUARES.a1) nextCastling &= ~CASTLE_FLAGS.WHITE_OOO;
    if (move.from === SQUARES.h8 || move.to === SQUARES.h8) nextCastling &= ~CASTLE_FLAGS.BLACK_OO;
    if (move.from === SQUARES.a8 || move.to === SQUARES.a8) nextCastling &= ~CASTLE_FLAGS.BLACK_OOO;

    const count = depth > 1 ? perft(board, swapColor(turn), nextCastling, nextEpSquare, depth - 1) : 1;
    result[uci] = count;

    unapplyMoveInternal(board, move, undo);
  }

  return result;
}
