﻿/**
 * @fileoverview High-performance 0x88 move generator and attack evaluator.
 * 
 * WHY: Generates pseudolegal moves via precalculated ray vectors and fast 0x88 bitwise
 * boundary checks, then filters strictly by simulating King safety to ensure 100% legal output.
 * 
 * // CRITICAL: Castling requires through-check, into-check, and out-of-check validation.
 */

import {
  BITS,
  BLACK,
  CASTLE_FLAGS,
  FLAGS,
  KING,
  KNIGHT,
  BISHOP,
  PAWN,
  PIECE_OFFSETS,
  QUEEN,
  ROOK,
  ROOKS,
  SQUARES,
  WHITE,
} from './constants.js';
import { Color, InternalMove, Piece, PieceSymbol } from './types.js';
import { chessRank, isSquareOnBoard, rank, swapColor } from './utils.js';

/**
 * Checks if a square is attacked by any piece of the specified attacking color.
 */
export function isSquareAttacked(board: (Piece | null)[], sq: number, attackingColor: Color): boolean {
  // 1. Pawn attacks
  const pawnAttackOffsets = attackingColor === WHITE ? [15, 17] : [-17, -15];
  for (const offset of pawnAttackOffsets) {
    const fromSq = sq + offset;
    if (isSquareOnBoard(fromSq)) {
      const p = board[fromSq];
      if (p && p.color === attackingColor && p.type === PAWN) {
        return true;
      }
    }
  }

  // 2. Knight attacks
  for (const offset of PIECE_OFFSETS[KNIGHT]) {
    const fromSq = sq + offset;
    if (isSquareOnBoard(fromSq)) {
      const p = board[fromSq];
      if (p && p.color === attackingColor && p.type === KNIGHT) {
        return true;
      }
    }
  }

  // 3. Bishop and Queen (Diagonal rays)
  for (const offset of PIECE_OFFSETS[BISHOP]) {
    let fromSq = sq + offset;
    while (isSquareOnBoard(fromSq)) {
      const p = board[fromSq];
      if (p) {
        if (p.color === attackingColor && (p.type === BISHOP || p.type === QUEEN)) {
          return true;
        }
        break; // Ray blocked by piece
      }
      fromSq += offset;
    }
  }

  // 4. Rook and Queen (Orthogonal rays)
  for (const offset of PIECE_OFFSETS[ROOK]) {
    let fromSq = sq + offset;
    while (isSquareOnBoard(fromSq)) {
      const p = board[fromSq];
      if (p) {
        if (p.color === attackingColor && (p.type === ROOK || p.type === QUEEN)) {
          return true;
        }
        break; // Ray blocked by piece
      }
      fromSq += offset;
    }
  }

  // 5. King attacks
  for (const offset of PIECE_OFFSETS[KING]) {
    const fromSq = sq + offset;
    if (isSquareOnBoard(fromSq)) {
      const p = board[fromSq];
      if (p && p.color === attackingColor && p.type === KING) {
        return true;
      }
    }
  }

  return false;
}

/**
 * Finds the 0x88 square coordinate of the King of the specified color.
 */
export function findKingSquare(board: (Piece | null)[], color: Color): number {
  for (let sq = 0; sq < 128; sq++) {
    if (!isSquareOnBoard(sq)) continue;
    const p = board[sq];
    if (p && p.type === KING && p.color === color) {
      return sq;
    }
  }
  return -1;
}

/**
 * Returns true if the King of the specified color is in check.
 */
export function isColorInCheck(board: (Piece | null)[], color: Color): boolean {
  const kingSq = findKingSquare(board, color);
  if (kingSq === -1) return false;
  return isSquareAttacked(board, kingSq, swapColor(color));
}

/**
 * Generates all pseudolegal moves for the active side.
 */
export function generatePseudolegalMoves(
  board: (Piece | null)[],
  turn: Color,
  castling: number,
  epSquare: number,
  fromFilterSquare?: number
): InternalMove[] {
  const moves: InternalMove[] = [];
  const opponent = swapColor(turn);

  const startSq = fromFilterSquare !== undefined ? fromFilterSquare : 0;
  const endSq = fromFilterSquare !== undefined ? fromFilterSquare : 127;

  for (let sq = startSq; sq <= endSq; sq++) {
    if (!isSquareOnBoard(sq)) continue;
    const piece = board[sq];
    if (!piece || piece.color !== turn) continue;

    const pieceType = piece.type;

    if (pieceType === PAWN) {
      const forwardOffset = turn === WHITE ? -16 : 16;
      const startRank = turn === WHITE ? 6 : 1;
      const promoRank = turn === WHITE ? 0 : 7;
      const currentRank = rank(sq);

      // Single step forward
      const nextSq = sq + forwardOffset;
      if (isSquareOnBoard(nextSq) && board[nextSq] === null) {
        if (rank(nextSq) === promoRank) {
          // Promotions
          for (const promo of [QUEEN, ROOK, BISHOP, KNIGHT] as PieceSymbol[]) {
            moves.push({
              color: turn,
              from: sq,
              to: nextSq,
              flags: BITS.PROMOTION,
              piece: PAWN,
              promotion: promo,
            });
          }
        } else {
          moves.push({
            color: turn,
            from: sq,
            to: nextSq,
            flags: BITS.NORMAL,
            piece: PAWN,
          });

          // Double step forward from starting rank
          const doubleSq = nextSq + forwardOffset;
          if (currentRank === startRank && board[doubleSq] === null) {
            moves.push({
              color: turn,
              from: sq,
              to: doubleSq,
              flags: BITS.BIG_PAWN,
              piece: PAWN,
            });
          }
        }
      }

      // Pawn Captures
      const captureOffsets = turn === WHITE ? [-17, -15] : [15, 17];
      for (const capOffset of captureOffsets) {
        const targetSq = sq + capOffset;
        if (!isSquareOnBoard(targetSq)) continue;

        const targetPiece = board[targetSq];
        if (targetPiece && targetPiece.color === opponent) {
          if (rank(targetSq) === promoRank) {
            for (const promo of [QUEEN, ROOK, BISHOP, KNIGHT] as PieceSymbol[]) {
              moves.push({
                color: turn,
                from: sq,
                to: targetSq,
                flags: BITS.PROMOTION | BITS.CAPTURE,
                piece: PAWN,
                captured: targetPiece.type,
                promotion: promo,
              });
            }
          } else {
            moves.push({
              color: turn,
              from: sq,
              to: targetSq,
              flags: BITS.CAPTURE,
              piece: PAWN,
              captured: targetPiece.type,
            });
          }
        } else if (targetSq === epSquare) {
          // En passant capture
          moves.push({
            color: turn,
            from: sq,
            to: targetSq,
            flags: BITS.EP_CAPTURE | BITS.CAPTURE,
            piece: PAWN,
            captured: PAWN,
          });
        }
      }
    } else if (pieceType === KNIGHT) {
      for (const offset of PIECE_OFFSETS[KNIGHT]) {
        const targetSq = sq + offset;
        if (!isSquareOnBoard(targetSq)) continue;

        const targetPiece = board[targetSq];
        if (targetPiece === null) {
          moves.push({
            color: turn,
            from: sq,
            to: targetSq,
            flags: BITS.NORMAL,
            piece: KNIGHT,
          });
        } else if (targetPiece.color === opponent) {
          moves.push({
            color: turn,
            from: sq,
            to: targetSq,
            flags: BITS.CAPTURE,
            piece: KNIGHT,
            captured: targetPiece.type,
          });
        }
      }
    } else if (pieceType === BISHOP || pieceType === ROOK || pieceType === QUEEN) {
      const offsets =
        pieceType === BISHOP
          ? PIECE_OFFSETS[BISHOP]
          : pieceType === ROOK
          ? PIECE_OFFSETS[ROOK]
          : PIECE_OFFSETS[QUEEN];

      for (const offset of offsets) {
        let targetSq = sq + offset;
        while (isSquareOnBoard(targetSq)) {
          const targetPiece = board[targetSq];
          if (targetPiece === null) {
            moves.push({
              color: turn,
              from: sq,
              to: targetSq,
              flags: BITS.NORMAL,
              piece: pieceType,
            });
          } else {
            if (targetPiece.color === opponent) {
              moves.push({
                color: turn,
                from: sq,
                to: targetSq,
                flags: BITS.CAPTURE,
                piece: pieceType,
                captured: targetPiece.type,
              });
            }
            break; // Ray blocked
          }
          targetSq += offset;
        }
      }
    } else if (pieceType === KING) {
      // Normal 1-square moves
      for (const offset of PIECE_OFFSETS[KING]) {
        const targetSq = sq + offset;
        if (!isSquareOnBoard(targetSq)) continue;

        const targetPiece = board[targetSq];
        if (targetPiece === null) {
          moves.push({
            color: turn,
            from: sq,
            to: targetSq,
            flags: BITS.NORMAL,
            piece: KING,
          });
        } else if (targetPiece.color === opponent) {
          moves.push({
            color: turn,
            from: sq,
            to: targetSq,
            flags: BITS.CAPTURE,
            piece: KING,
            captured: targetPiece.type,
          });
        }
      }

      // Castling moves (only when evaluating king moves)
      if (fromFilterSquare === undefined || fromFilterSquare === sq) {
        // King cannot castle if already in check
        if (!isSquareAttacked(board, sq, opponent)) {
          const castlingDef = ROOKS[turn];

          // Kingside Castling (O-O)
          const ksideFlag = turn === WHITE ? CASTLE_FLAGS.WHITE_OO : CASTLE_FLAGS.BLACK_OO;
          if (castling & ksideFlag) {
            const kside = castlingDef.k;
            const rookPiece = board[kside.rookFrom];
            if (rookPiece && rookPiece.type === ROOK && rookPiece.color === turn) {
              // Check empty squares
              const empty = kside.empty.every((s) => board[s] === null);
              if (empty) {
                // Check that King does not pass through check
                const safe = kside.test.every((s) => !isSquareAttacked(board, s, opponent));
                if (safe) {
                  moves.push({
                    color: turn,
                    from: sq,
                    to: kside.to,
                    flags: BITS.KSIDE_CASTLE,
                    piece: KING,
                  });
                }
              }
            }
          }

          // Queenside Castling (O-O-O)
          const qsideFlag = turn === WHITE ? CASTLE_FLAGS.WHITE_OOO : CASTLE_FLAGS.BLACK_OOO;
          if (castling & qsideFlag) {
            const qside = castlingDef.q;
            const rookPiece = board[qside.rookFrom];
            if (rookPiece && rookPiece.type === ROOK && rookPiece.color === turn) {
              // Check empty squares
              const empty = qside.empty.every((s) => board[s] === null);
              if (empty) {
                // Check that King does not pass through check
                const safe = qside.test.every((s) => !isSquareAttacked(board, s, opponent));
                if (safe) {
                  moves.push({
                    color: turn,
                    from: sq,
                    to: qside.to,
                    flags: BITS.QSIDE_CASTLE,
                    piece: KING,
                  });
                }
              }
            }
          }
        }
      }
    }
  }

  return moves;
}

/**
 * Makes an internal move on the board array and returns an undo token.
 */
export function applyMoveInternal(
  board: (Piece | null)[],
  move: InternalMove
): { capturedPiece: Piece | null; epSquareCaptured: number } {
  const movingPiece = board[move.from]!;
  let capturedPiece: Piece | null = null;
  let epSquareCaptured = -1;

  if (move.flags & BITS.EP_CAPTURE) {
    // Pawn was captured en passant on the rank behind destination
    const epCapOffset = move.color === WHITE ? 16 : -16;
    epSquareCaptured = move.to + epCapOffset;
    capturedPiece = board[epSquareCaptured];
    board[epSquareCaptured] = null;
  } else if (move.flags & BITS.CAPTURE) {
    capturedPiece = board[move.to];
  }

  // Move the piece
  board[move.from] = null;

  if (move.flags & BITS.PROMOTION) {
    board[move.to] = {
      type: move.promotion || QUEEN,
      color: move.color,
    };
  } else {
    board[move.to] = movingPiece;
  }

  // If castling, move the rook as well
  if (move.flags & BITS.KSIDE_CASTLE) {
    const rookFrom = move.color === WHITE ? SQUARES.h1 : SQUARES.h8;
    const rookTo = move.color === WHITE ? SQUARES.f1 : SQUARES.f8;
    board[rookTo] = board[rookFrom];
    board[rookFrom] = null;
  } else if (move.flags & BITS.QSIDE_CASTLE) {
    const rookFrom = move.color === WHITE ? SQUARES.a1 : SQUARES.a8;
    const rookTo = move.color === WHITE ? SQUARES.d1 : SQUARES.d8;
    board[rookTo] = board[rookFrom];
    board[rookFrom] = null;
  }

  return { capturedPiece, epSquareCaptured };
}

/**
 * Undoes an internal move on the board array.
 */
export function unapplyMoveInternal(
  board: (Piece | null)[],
  move: InternalMove,
  undo: { capturedPiece: Piece | null; epSquareCaptured: number }
): void {
  // If castling, revert rook
  if (move.flags & BITS.KSIDE_CASTLE) {
    const rookFrom = move.color === WHITE ? SQUARES.h1 : SQUARES.h8;
    const rookTo = move.color === WHITE ? SQUARES.f1 : SQUARES.f8;
    board[rookFrom] = board[rookTo];
    board[rookTo] = null;
  } else if (move.flags & BITS.QSIDE_CASTLE) {
    const rookFrom = move.color === WHITE ? SQUARES.a1 : SQUARES.a8;
    const rookTo = move.color === WHITE ? SQUARES.d1 : SQUARES.d8;
    board[rookFrom] = board[rookTo];
    board[rookTo] = null;
  }

  // Restore piece back to 'from' square
  board[move.from] = {
    type: move.piece,
    color: move.color,
  };

  // Restore destination square
  if (move.flags & BITS.EP_CAPTURE) {
    board[move.to] = null;
    board[undo.epSquareCaptured] = undo.capturedPiece;
  } else {
    board[move.to] = undo.capturedPiece;
  }
}

/**
 * Generates all strictly legal moves for the active side.
 */
export function generateLegalMoves(
  board: (Piece | null)[],
  turn: Color,
  castling: number,
  epSquare: number,
  fromFilterSquare?: number
): InternalMove[] {
  const pseudoMoves = generatePseudolegalMoves(board, turn, castling, epSquare, fromFilterSquare);
  const legalMoves: InternalMove[] = [];

  for (const move of pseudoMoves) {
    const undo = applyMoveInternal(board, move);
    const inCheck = isColorInCheck(board, turn);
    unapplyMoveInternal(board, move, undo);

    if (!inCheck) {
      legalMoves.push(move);
    }
  }

  return legalMoves;
}
