﻿/**
 * @fileoverview Core chess constants, 0x88 board coordinate definitions,
 * ray vectors, and bitflags for @von/chess.
 * 
 * WHY: 0x88 mailbox representation provides O(1) off-board detection via `(sq & 0x88) === 0`,
 * while keeping memory footprint minimal and avoiding BigInt operations.
 * 
 * // CRITICAL: Modification of square indices or ray offsets will corrupt legal move generation.
 */

export const WHITE = 'w' as const;
export const BLACK = 'b' as const;

export const PAWN = 'p' as const;
export const KNIGHT = 'n' as const;
export const BISHOP = 'b' as const;
export const ROOK = 'r' as const;
export const QUEEN = 'q' as const;
export const KING = 'k' as const;

export const DEFAULT_POSITION = 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';

export const EMPTY = 0;

/**
 * Move flag representations compatible with chess.js standard
 * n: non-capture
 * b: double pawn push
 * e: en passant capture
 * c: standard capture
 * p: promotion
 * cp: capture promotion
 * k: kingside castle
 * q: queenside castle
 */
export const BITS = {
  NORMAL: 1,
  CAPTURE: 2,
  BIG_PAWN: 4,
  EP_CAPTURE: 8,
  PROMOTION: 16,
  KSIDE_CASTLE: 32,
  QSIDE_CASTLE: 64,
} as const;

export const FLAGS = {
  NORMAL: 'n',
  CAPTURE: 'c',
  BIG_PAWN: 'b',
  EP_CAPTURE: 'e',
  PROMOTION: 'p',
  EP_PROMOTION: 'cp',
  KSIDE_CASTLE: 'k',
  QSIDE_CASTLE: 'q',
} as const;

/**
 * Castling availability bitmasks
 */
export const CASTLE_FLAGS = {
  NONE: 0,
  WHITE_OO: 1,
  WHITE_OOO: 2,
  BLACK_OO: 4,
  BLACK_OOO: 8,
} as const;

/**
 * 0x88 Square indices:
 * Row 8: a8=0 ... h8=7
 * Row 7: a7=16 ... h7=23
 * Row 1: a1=112 ... h1=119
 */
