    q: { from: SQUARES.e8, to: SQUARES.c8, rookFrom: SQUARES.a8, rookTo: SQUARES.d8, empty: [SQUARES.b8, SQUARES.c8, SQUARES.d8], test: [SQUARES.e8, SQUARES.d8, SQUARES.c8] }
