﻿/**
 * @fileoverview Disambiguated Standard Algebraic Notation (SAN) generator and parser.
 * 
 * WHY: Generates FIDE-compliant, cleanly disambiguated move notation (file, rank, or both)
 * and accurately applies check (+) and checkmate (#) suffixes.
 */

import {
  BITS,
  KING,
  PAWN,
  QUEEN,
  ROOK,
  SQUARES,
  WHITE,
} from './constants.js';
import { Color, InternalMove, Piece, PieceSymbol, Square } from './types.js';
import {
  algebraicToSquare,
  chessRank,
  file,
  isSquareOnBoard,
  rank,
  squareToAlgebraic,
  swapColor,
} from './utils.js';
import {
  applyMoveInternal,
  generateLegalMoves,
  isColorInCheck,
  unapplyMoveInternal,
} from './move-generator.js';

const FILES = 'abcdefgh';

/**
 * Converts an internal move to Standard Algebraic Notation (SAN).
 */
export function moveToSan(
  board: (Piece | null)[],
  turn: Color,
  castling: number,
  epSquare: number,
  move: InternalMove,
  legalMoves?: InternalMove[]
): string {
  // 1. Castling
  if (move.flags & BITS.KSIDE_CASTLE) {
    return appendCheckOrCheckmate(board, turn, castling, epSquare, move, 'O-O');
  }
  if (move.flags & BITS.QSIDE_CASTLE) {
    return appendCheckOrCheckmate(board, turn, castling, epSquare, move, 'O-O-O');
  }

  let san = '';
  const pieceType = move.piece;
  const toAlgebraic = squareToAlgebraic(move.to);

  // 2. Pawns
  if (pieceType === PAWN) {
    if (move.flags & BITS.CAPTURE) {
      const fromFile = FILES[file(move.from)];
      san += `${fromFile}x${toAlgebraic}`;
    } else {
      san += toAlgebraic;
    }

    if (move.flags & BITS.PROMOTION && move.promotion) {
      san += `=${move.promotion.toUpperCase()}`;
    }

    return appendCheckOrCheckmate(board, turn, castling, epSquare, move, san);
  }

  // 3. Pieces (N, B, R, Q, K)
  san += pieceType.toUpperCase();

  // Disambiguation
  if (pieceType !== KING) {
    const allLegals = legalMoves || generateLegalMoves(board, turn, castling, epSquare);
    const ambiguousMoves = allLegals.filter(
      (m) =>
        m.from !== move.from &&
        m.to === move.to &&
        m.piece === pieceType &&
        m.color === turn
    );

    if (ambiguousMoves.length > 0) {
      const moveFromFile = file(move.from);
      const moveFromRank = chessRank(move.from);

      const sameFile = ambiguousMoves.some((m) => file(m.from) === moveFromFile);
      const sameRank = ambiguousMoves.some((m) => chessRank(m.from) === moveFromRank);

      if (!sameFile) {
        // Disambiguate by file
        san += FILES[moveFromFile];
      } else if (!sameRank) {
        // Disambiguate by rank
        san += moveFromRank.toString();
      } else {
        // Disambiguate by both file and rank
        san += `${FILES[moveFromFile]}${moveFromRank}`;
      }
    }
  }

  // Capture indicator
  if (move.flags & BITS.CAPTURE) {
    san += 'x';
  }

  san += toAlgebraic;

  return appendCheckOrCheckmate(board, turn, castling, epSquare, move, san);
}

/**
 * Simulates making the move to evaluate check or checkmate state.
 */
function appendCheckOrCheckmate(
  board: (Piece | null)[],
  turn: Color,
  castling: number,
  epSquare: number,
  move: InternalMove,
  san: string
): string {
  const undo = applyMoveInternal(board, move);
  const opponent = swapColor(turn);

  // Evaluate state for opponent
  const inCheck = isColorInCheck(board, opponent);
  let isMate = false;

  if (inCheck) {
    // Check if opponent has any legal responses
    const nextLegals = generateLegalMoves(board, opponent, castling, -1);
    if (nextLegals.length === 0) {
      isMate = true;
    }
  }

  unapplyMoveInternal(board, move, undo);

  if (isMate) {
    return san + '#';
  }
  if (inCheck) {
    return san + '+';
  }
  return san;
}

/**
 * Parses SAN or UCI string into an internal move matching current position's legal moves.
 */
export function parseSan(
  board: (Piece | null)[],
  turn: Color,
  castling: number,
  epSquare: number,
  sanString: string
): InternalMove | null {
  const clean = sanString.trim().replace(/[+#!?]/g, '');
  const legalMoves = generateLegalMoves(board, turn, castling, epSquare);

  // 1. Try matching exact SAN
  for (const move of legalMoves) {
    const generatedSan = moveToSan(board, turn, castling, epSquare, move, legalMoves);
    const generatedClean = generatedSan.replace(/[+#!?]/g, '');
    if (clean === generatedClean || clean === generatedSan) {
      return move;
    }
  }

  // 2. Try matching UCI / coordinate move (e.g. 'e2e4', 'e7e8q')
  const uciMatch = clean.match(/^([a-h][1-8])[-x]?([a-h][1-8])(=?[qrbnQRBN])?$/);
  if (uciMatch) {
    const from = algebraicToSquare(uciMatch[1]);
    const to = algebraicToSquare(uciMatch[2]);
    const promo = uciMatch[3] ? (uciMatch[3].replace('=', '').toLowerCase() as PieceSymbol) : undefined;

    for (const move of legalMoves) {
      if (move.from === from && move.to === to) {
        if (promo) {
          if (move.promotion === promo) return move;
        } else if (!move.promotion || move.promotion === QUEEN) {
          return move;
        }
      }
    }
  }

  return null;
}
