﻿/**
 * @fileoverview Utility functions for board coordinate manipulation,
 * 0x88 address arithmetic, and piece conversions.
 */

import { SQUARES, WHITE, BLACK } from './constants.js';
import { Color, Piece, PieceSymbol, Square } from './types.js';

const ALGEBRAIC_MAP: Square[] = new Array(128);
const SQUARE_NAMES = Object.keys(SQUARES) as Square[];

for (const name of SQUARE_NAMES) {
  const index = SQUARES[name];
  ALGEBRAIC_MAP[index] = name;
}

/**
 * Returns true if the 0x88 square coordinate is within the 8x8 chessboard.
 */
export function isSquareOnBoard(sq: number): boolean {
  return (sq & 0x88) === 0;
}

/**
 * Converts a 0x88 index to an algebraic square notation (e.g. 0x00 -> 'a8', 0x77 -> 'h1').
 */
export function squareToAlgebraic(sq: number): Square {
  return ALGEBRAIC_MAP[sq];
}

/**
 * Converts algebraic square notation (e.g. 'e4') to a 0x88 index.
 */
export function algebraicToSquare(name: string): number {
  if (name in SQUARES) {
    return SQUARES[name as Square];
  }
  return -1;
}

/**
 * Returns the rank of a 0x88 square (0 = rank 8, 7 = rank 1).
 */
export function rank(sq: number): number {
  return sq >> 4;
}

/**
 * Returns the 1-based chess rank (1 to 8).
 */
export function chessRank(sq: number): number {
  return 8 - (sq >> 4);
}

/**
 * Returns the file of a 0x88 square (0 = file a, 7 = file h).
 */
export function file(sq: number): number {
  return sq & 15;
}

/**
 * Returns the opposite color.
 */
export function swapColor(color: Color): Color {
  return color === WHITE ? BLACK : WHITE;
}

/**
 * Maps single FEN character to Piece object.
 */
export function fenCharToPiece(char: string): Piece | null {
  const lower = char.toLowerCase() as PieceSymbol;
  if (!['p', 'n', 'b', 'r', 'q', 'k'].includes(lower)) return null;
  return {
    type: lower,
    color: char === char.toUpperCase() ? WHITE : BLACK,
  };
}

/**
 * Maps Piece object to FEN character.
 */
export function pieceToFenChar(piece: Piece): string {
  return piece.color === WHITE ? piece.type.toUpperCase() : piece.type.toLowerCase();
}
