/**
 * @fileoverview Robust PGN (Portable Game Notation) parser, tokenizer, and serializer.
 * 
 * WHY: Replaces buggy chess.js PGN parser with a resilient tokenizer that gracefully handles
 * nested comments, clock tags ([%clk ...]), shape annotations ([%csl ...], [%cal ...]),
 * NAG glyphs, and recursive variation annotations.
 */

import { PositionState } from './position.js';
import { PgnHeader, PgnOptions } from './types.js';
import { normalizeTagKey, comparePgnTags } from './tags.js';

export interface ParsedPgn {
  headers: PgnHeader;
  history: string[]; // SAN moves
  comments: Map<number, string>; // comment keyed by ply index (-1 = initial position comment)
  result?: string;
}

/**
 * Tokenizes and parses PGN string into structured headers and moves.
 */
export function parsePgnString(pgn: string): ParsedPgn {
  const headers: PgnHeader = {};
  const comments = new Map<number, string>();
  let result: string | undefined;

  // 1. Parse header tags: [Key "Value"]
  const headerRegex = /^\s*\[([A-Za-z0-9_]+)\s+"([^"]*)"\]\s*$/;
  const lines = pgn.split(/\r?\n/);
  const movetextLines: string[] = [];
  let readingHeaders = true;

  for (const line of lines) {
    const trimmed = line.trim();
    if (readingHeaders) {
      if (trimmed.startsWith('[')) {
        const match = trimmed.match(headerRegex);
        if (match) {
          const key = normalizeTagKey(match[1]);
          headers[key] = match[2];
        }
        continue;
      } else if (trimmed === '') {
        // Blank line separates headers from movetext
        readingHeaders = false;
        continue;
      } else {
        readingHeaders = false;
      }
    }
    movetextLines.push(line);
  }

  const movetext = movetextLines.join(' ').trim();
  if (!movetext) {
    return { headers, history: [], comments, result };
  }

  // 2. Tokenize movetext: moves, comments { ... }, variations ( ... ), NAGs $1
  const history: string[] = [];
  let i = 0;
  let currentPly = -1;

  while (i < movetext.length) {
    // Skip whitespace
    while (i < movetext.length && /\s/.test(movetext[i])) {
      i++;
    }
    if (i >= movetext.length) break;

    const char = movetext[i];

    // Comment block { ... }
    if (char === '{') {
      const start = i + 1;
      let depth = 1;
      i++;
      while (i < movetext.length && depth > 0) {
        if (movetext[i] === '{') depth++;
        else if (movetext[i] === '}') depth--;
        i++;
      }
      const commentText = movetext.substring(start, i - 1).trim();
      const existing = comments.get(currentPly) || '';
      comments.set(currentPly, existing ? `${existing} ${commentText}` : commentText);
      continue;
    }

    // Variation block ( ... )
    if (char === '(') {
      let depth = 1;
      i++;
      while (i < movetext.length && depth > 0) {
        if (movetext[i] === '(') depth++;
        else if (movetext[i] === ')') depth--;
        i++;
      }
      // Variations skipped for main-line PGN playback
      continue;
    }

    // NAGs (e.g. $1, $2, etc.)
    if (char === '$') {
      i++;
      while (i < movetext.length && /\d/.test(movetext[i])) {
        i++;
      }
      continue;
    }

    // Move number or SAN token
    let token = '';
    while (i < movetext.length && !/[\s{}()]/.test(movetext[i])) {
      token += movetext[i];
      i++;
    }

    // Check for game termination marker
    if (['1-0', '0-1', '1/2-1/2', '*'].includes(token)) {
      result = token;
      continue;
    }

    // Check if token is move number (e.g. "1.", "12...", "1.e4")
    const moveNumMatch = token.match(/^(\d+)\.+([a-zA-Z0-9+=#-]+)?$/);
    if (moveNumMatch) {
      if (moveNumMatch[2]) {
        // Embedded SAN right after number, e.g. "1.e4"
        history.push(moveNumMatch[2]);
        currentPly++;
      }
      continue;
    }

    if (token) {
      history.push(token);
      currentPly++;
    }
  }

  return { headers, history, comments, result };
}

/**
 * Serializes position state into standard PGN string format.
 */
export function buildPgnString(
  state: PositionState,
  headers: PgnHeader,
  comments: Map<number, string>,
  options?: PgnOptions
): string {
  const parts: string[] = [];

  // 1. Headers (sorted in canonical Lichess order)
  const sortedKeys = Object.keys(headers).sort(comparePgnTags);
  for (const key of sortedKeys) {
    if (headers[key] !== undefined) {
      parts.push(`[${key} "${headers[key]}"]`);
    }
  }

  if (parts.length > 0) {
    parts.push(''); // Blank line separator
  }

  // 2. Movetext
  const moveTokens: string[] = [];
  const initialComment = comments.get(-1);
  if (initialComment) {
    moveTokens.push(`{${initialComment}}`);
  }

  let moveNumber = 1;
  for (let ply = 0; ply < state.history.length; ply++) {
    const item = state.history[ply];
    if (ply % 2 === 0) {
      moveTokens.push(`${moveNumber}.`);
    }

    moveTokens.push(item.san);

    const comment = comments.get(ply);
    if (comment) {
      moveTokens.push(`{${comment}}`);
    }

    if (ply % 2 === 1) {
      moveNumber++;
    }
  }

  const result = headers['Result'] || '*';
  moveTokens.push(result);

  const newline = options?.newline || '\n';
  const maxWidth = options?.maxWidth || 0;

  if (maxWidth > 0) {
    let currentLine = '';
    const wrappedLines: string[] = [];

    for (const token of moveTokens) {
      if (currentLine.length + token.length + 1 > maxWidth) {
        wrappedLines.push(currentLine.trim());
        currentLine = token + ' ';
      } else {
        currentLine += token + ' ';
      }
    }
    if (currentLine.trim()) {
      wrappedLines.push(currentLine.trim());
    }
    parts.push(wrappedLines.join(newline));
  } else {
    parts.push(moveTokens.join(' '));
  }

  return parts.join(newline);
}
