/**
 * @fileoverview Main entry point for @von/chess.
 * Provides the `Chess` engine class with 100% drop-in compatibility for chess.js (v1.x),
 * legacy aliases (v0.12), and tailored extensions for VON.CHESS.
 * 
 * WHY: Replaces 3rd-party chess.js with zero refactoring needed across callers,
 * while improving PGN resilience and providing color-agnostic king safety for Bughouse.
 */

import { DEFAULT_POSITION, SQUARES, WHITE, BLACK } from './constants.js';
import {
  Color,
  HistoryOptions,
  Move,
  MoveInput,
  MovesOptions,
  PgnHeader,
  PgnOptions,
  Piece,
  PieceSymbol,
  Square,
  ValidationResult,
  VerboseMove,
} from './types.js';
import { parseFen, validateFen } from './fen.js';
import { PositionState, formatMoveFlags } from './position.js';
import { buildPgnString, parsePgnString } from './pgn.js';
import { perft, perftDivide } from './perft.js';
import { squareToAlgebraic } from './utils.js';
import {
  CANONICAL_PGN_TAGS,
  normalizeTagKey,
  cleanTagValue,
  getTagRank,
  comparePgnTags,
  sanitizePgnHeaders,
} from './tags.js';

export type {
  Color,
  PieceSymbol,
  Square,
  Piece,
  Move,
  VerboseMove,
  MoveInput,
  MovesOptions,
  HistoryOptions,
  PgnOptions,
  PgnHeader,
  ValidationResult,
};

export {
  validateFen,
  DEFAULT_POSITION,
  SQUARES,
  WHITE,
  BLACK,
  CANONICAL_PGN_TAGS,
  normalizeTagKey,
  cleanTagValue,
  getTagRank,
  comparePgnTags,
  sanitizePgnHeaders,
};

export class Chess {
  private state: PositionState;
  private headers: PgnHeader = {};
  private comments: Map<number, string> = new Map();

  constructor(fen: string = DEFAULT_POSITION) {
    this.state = new PositionState(fen);
  }

  /**
   * Resets the game to the default starting position.
   */
  reset(): void {
    this.state.reset();
    this.headers = {};
    this.comments.clear();
  }

  /**
   * Clears the board completely.
   */
  clear(): void {
    this.state.clear();
    this.headers = {};
    this.comments.clear();
  }

  /**
   * Loads a FEN string. Throws error if invalid.
   */
  load(fen: string): void {
    this.state.load(fen);
    this.headers = {};
    this.comments.clear();
  }

  /**
   * Returns current FEN.
   */
  fen(): string {
    return this.state.fen();
  }

  /**
   * Returns the current turn ('w' or 'b').
   */
  turn(): Color {
    return this.state.turn;
  }

  /**
   * Returns the current fullmove number.
   */
  moveNumber(): number {
    return this.state.fullMoves;
  }

  /**
   * Executes a move.
   * Can be SAN string (e.g. 'e4', 'Nf3', 'O-O') or MoveInput ({ from: 'e2', to: 'e4', promotion?: 'q' }).
   * Returns Move on success or throws error.
   */
  move(moveInput: string | MoveInput, _options?: { strict?: boolean }): Move {
    const result = this.state.makeMove(moveInput);
    if (!result) {
      throw new Error(`Invalid move: ${typeof moveInput === 'string' ? moveInput : JSON.stringify(moveInput)}`);
    }
    return result;
  }

  /**
   * Undoes the last move. Returns Move or null if no moves to undo.
   */
  undo(): Move | null {
    return this.state.undoMove();
  }

  /**
   * Returns an array of legal moves with full overloads matching chess.js.
   */
  moves(options: { verbose: true } & MovesOptions): Move[];
  moves(options?: { verbose?: false } & MovesOptions): string[];
  moves(options?: MovesOptions): (string | Move)[];
  moves(options?: MovesOptions): (string | Move)[] {
    return this.state.moves(options);
  }

  /**
   * Returns move history with overloads matching chess.js.
   */
  history(options: { verbose: true }): Move[];
  history(options?: { verbose?: false }): string[];
  history(options?: HistoryOptions): (string | Move)[];
  history(options?: HistoryOptions): (string | Move)[] {
    if (options?.verbose) {
      return this.state.history.map((h) => ({
        color: h.move.color,
        from: squareToAlgebraic(h.move.from),
        to: squareToAlgebraic(h.move.to),
        piece: h.move.piece,
        captured: h.move.captured,
        promotion: h.move.promotion,
        flags: formatMoveFlags(h.move.flags),
        san: h.san,
        lan: `${squareToAlgebraic(h.move.from)}${squareToAlgebraic(h.move.to)}${h.move.promotion || ''}`,
        before: h.beforeFen,
        after: h.afterFen,
      }));
    }
    return this.state.history.map((h) => h.san);
  }

  /**
   * Returns an 8x8 matrix representing board state.
   */
  board(): ({ square: Square; type: PieceSymbol; color: Color } | null)[][] {
    const grid: ({ square: Square; type: PieceSymbol; color: Color } | null)[][] = [];
    const files = 'abcdefgh';

    for (let r = 0; r < 8; r++) {
      const row: ({ square: Square; type: PieceSymbol; color: Color } | null)[] = [];
      for (let f = 0; f < 8; f++) {
        const sq = (r << 4) + f;
        const squareName = (files[f] + (8 - r)) as Square;
        const p = this.state.board[sq];
        if (p) {
          row.push({
            square: squareName,
            type: p.type,
            color: p.color,
          });
        } else {
          row.push(null);
        }
      }
      grid.push(row);
    }

    return grid;
  }

  /**
   * Returns the piece at a given square or null.
   */
  get(square: Square | string): Piece | null {
    return this.state.get(square);
  }

  /**
   * Places a piece on a square.
   */
  put(piece: Piece, square: Square | string): boolean {
    return this.state.put(piece, square);
  }

  /**
   * Removes a piece from a square.
   */
  remove(square: Square | string): Piece | null {
    return this.state.remove(square);
  }

  /**
   * Returns true if king is in check.
   * If color parameter is supplied, tests safety for that color (Bughouse extension).
   */
  isCheck(color?: Color): boolean {
    return this.state.isCheck(color);
  }

  /**
   * Modern chess.js alias for isCheck.
   */
  inCheck(color?: Color): boolean {
    return this.isCheck(color);
  }

  /**
   * Returns true if active player is checkmated.
   */
  isCheckmate(): boolean {
    return this.state.isCheckmate();
  }

  /**
   * Returns true if active player is stalemated.
   */
  isStalemate(): boolean {
    return this.state.isStalemate();
  }

  /**
   * Returns true if position has repeated 3 times.
   */
  isThreefoldRepetition(): boolean {
    return this.state.isThreefoldRepetition();
  }

  /**
   * Returns true if material on board cannot produce checkmate.
   */
  isInsufficientMaterial(): boolean {
    return this.state.isInsufficientMaterial();
  }

  /**
   * Returns true if game is drawn (stalemate, repetition, 50-move, or insufficient material).
   */
  isDraw(): boolean {
    return this.state.isDraw();
  }

  /**
   * Returns true if game is in a terminal state (checkmate or draw).
   */
  isGameOver(): boolean {
    return this.state.isGameOver();
  }

  /**
   * Manages PGN headers with exact chess.js overloads.
   */
  header(): PgnHeader;
  header(key: string): string | undefined;
  header(...args: string[]): PgnHeader | string | undefined;
  header(...args: string[]): PgnHeader | string | undefined {
    if (args.length === 0) {
      return { ...this.headers };
    }
    if (args.length === 1) {
      return this.headers[args[0]];
    }
    for (let i = 0; i < args.length; i += 2) {
      if (args[i + 1] !== undefined) {
        this.headers[args[i]] = args[i + 1];
      }
    }
    return { ...this.headers };
  }

  /**
   * Exports PGN string.
   */
  pgn(options?: PgnOptions): string {
    return buildPgnString(this.state, this.headers, this.comments, options);
  }

  /**
   * Imports PGN string.
   */
  loadPgn(pgn: string, _options?: { strict?: boolean; newline?: string }): void {
    const parsed = parsePgnString(pgn);
    this.reset();
    this.headers = parsed.headers;
    this.comments = parsed.comments;

    for (const san of parsed.history) {
      const res = this.state.makeMove(san);
      if (!res) {
        throw new Error(`Failed to parse PGN move: ${san}`);
      }
    }
  }

  /**
   * Comments manipulation
   */
  getComment(): string | undefined {
    return this.comments.get(this.state.history.length - 1);
  }

  setComment(comment: string): void {
    this.comments.set(this.state.history.length - 1, comment);
  }

  deleteComment(): string | undefined {
    const key = this.state.history.length - 1;
    const comment = this.comments.get(key);
    this.comments.delete(key);
    return comment;
  }

  getComments(): { fen: string; comment: string }[] {
    const result: { fen: string; comment: string }[] = [];
    for (const [ply, comment] of this.comments.entries()) {
      if (ply >= 0 && ply < this.state.history.length) {
        result.push({ fen: this.state.history[ply].afterFen, comment });
      }
    }
    return result;
  }

  deleteComments(): { fen: string; comment: string }[] {
    const comments = this.getComments();
    this.comments.clear();
    return comments;
  }

  /**
   * Runs Perft at specified depth on current position.
   */
  perft(depth: number): number {
    return perft(
      this.state.board,
      this.state.turn,
      this.state.castling,
      this.state.epSquare,
      depth
    );
  }

  /**
   * Runs Perft divide at specified depth.
   */
  perftDivide(depth: number): Record<string, number> {
    return perftDivide(
      this.state.board,
      this.state.turn,
      this.state.castling,
      this.state.epSquare,
      depth
    );
  }

  // --- Backwards-compatible aliases for chess.js v0.12 API ---
  /** @deprecated Use `isCheck()` instead. */
  in_check(): boolean {
    return this.isCheck();
  }

  /** @deprecated Use `isCheckmate()` instead. */
  in_checkmate(): boolean {
    return this.isCheckmate();
  }

  /** @deprecated Use `isStalemate()` instead. */
  in_stalemate(): boolean {
    return this.isStalemate();
  }

  /** @deprecated Use `isDraw()` instead. */
  in_draw(): boolean {
    return this.isDraw();
  }

  /** @deprecated Use `isThreefoldRepetition()` instead. */
  in_threefold_repetition(): boolean {
    return this.isThreefoldRepetition();
  }

  /** @deprecated Use `isInsufficientMaterial()` instead. */
  insufficient_material(): boolean {
    return this.isInsufficientMaterial();
  }

  /** @deprecated Use `isGameOver()` instead. */
  game_over(): boolean {
    return this.isGameOver();
  }

  /** @deprecated Use `validateFen(fen)` instead. */
  static validate_fen(fen: string): ValidationResult {
    return validateFen(fen);
  }
}

export default Chess;
